function o(t){if(t==null||t==="")return"-";if(typeof t=="string"&&/^\d{4}\.\d{1,2}\.\d{1,2}$/.test(t))return t;const e=typeof t=="string"?new Date(t.replace(/-/g,"/").replace(/\./g,"/")):t instanceof Date?t:new Date(t);if(isNaN(e.getTime()))return String(t);const n=e.getFullYear(),r=e.getMonth()+1,i=e.getDate();return`${n}.${r}.${i}`}function u(t){return t==null||t===""||typeof t=="number"&&isNaN(t)?"/":Number(t).toLocaleString("zh-CN",{minimumFractionDigits:2,maximumFractionDigits:2})}export{o as a,u as f};
